CREATE TABLE IF NOT EXISTS "public"."dcb_events_full"
(
    "id"                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "event_type"        character varying(255) NOT NULL,
    "data"              JSONB NOT NULL,
    "created_at"        timestamptz NOT NULL DEFAULT NOW()
) WITH (oids = false);

CREATE TABLE IF NOT EXISTS "public"."dcb_flags_full"
(
    "id"                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "database"          character varying(255) NOT NULL,
    "aggregate_name"    character varying(255) NOT NULL,
    "aggregate_id"      character varying(255) NOT NULL,
    "event_id"          integer REFERENCES dcb_events_full (id)
) WITH (oids = false);

CREATE UNIQUE INDEX "dcb_flags_full_idx"
    ON "public"."dcb_flags_full" ("database", "aggregate_name", "aggregate_id", "event_id");
